-- All ids are snowflakes (time-ordered 64-bit integers), generated by the server.

CREATE TABLE users (
    id             BIGINT PRIMARY KEY,
    discord_id     TEXT NOT NULL UNIQUE,
    username       TEXT NOT NULL,
    display_name   TEXT,
    avatar         TEXT,             -- path under /uploads, mirrored from Discord on first login
    banner         TEXT,
    accent_color   INTEGER,
    bio            TEXT NOT NULL DEFAULT '',
    status         TEXT NOT NULL DEFAULT 'online',   -- online | idle | dnd | invisible
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE sessions (
    token_hash  BYTEA PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);

CREATE TABLE guilds (
    id          BIGINT PRIMARY KEY,
    name        TEXT NOT NULL,
    icon        TEXT,
    owner_id    BIGINT NOT NULL REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE members (
    guild_id   BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    user_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    nickname   TEXT,
    joined_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (guild_id, user_id)
);
CREATE INDEX members_user ON members(user_id);

-- kind: 0 = text, 1 = dm, 2 = voice, 4 = category
CREATE TABLE channels (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT REFERENCES guilds(id) ON DELETE CASCADE,
    kind        SMALLINT NOT NULL,
    name        TEXT NOT NULL DEFAULT '',
    topic       TEXT NOT NULL DEFAULT '',
    position    INTEGER NOT NULL DEFAULT 0,
    parent_id   BIGINT REFERENCES channels(id) ON DELETE SET NULL,
    last_message_id BIGINT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX channels_guild ON channels(guild_id);

CREATE TABLE dm_recipients (
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (channel_id, user_id)
);
CREATE INDEX dm_recipients_user ON dm_recipients(user_id);

CREATE TABLE messages (
    id           BIGINT PRIMARY KEY,
    channel_id   BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    author_id    BIGINT NOT NULL REFERENCES users(id),
    content      TEXT NOT NULL,
    reply_to     BIGINT,
    attachments  JSONB NOT NULL DEFAULT '[]',
    edited_at    TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX messages_channel ON messages(channel_id, id DESC);

CREATE TABLE reactions (
    message_id  BIGINT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    emoji       TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (message_id, emoji, user_id)
);

CREATE TABLE invites (
    code        TEXT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    creator_id  BIGINT NOT NULL REFERENCES users(id),
    uses        INTEGER NOT NULL DEFAULT 0,
    max_uses    INTEGER,
    expires_at  TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE read_states (
    user_id       BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    channel_id    BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    last_read_id  BIGINT NOT NULL,
    PRIMARY KEY (user_id, channel_id)
);
